+    let (output_tx, output_rx) = broadcast::channel::<Vec<u8>>(OUTPUT_CHANNEL_CAPACITY);
+    drop(output_rx);
+    for _ in 0..OUTPUT_CHANNEL_CAPACITY * 2 {
+        send_output_chunk(&output_tx, vec![0]);
+    }
