<summary>Standalone Node.js reproduction (standard library only)</summary>

```js
#!/usr/bin/env node

import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import http from "node:http";
import { fileURLToPath } from "node:url";
import path from "node:path";

const fixtureRoot = path.dirname(fileURLToPath(import.meta.url));
const fixtureHome = path.join(fixtureRoot, `fixture-home-${process.pid}`);
const fixtureWorkdir = path.join(fixtureRoot, "fixture-workdir");
const evidencePath = path.join(fixtureRoot, "fixture-evidence.json");
const consolePath = path.join(fixtureRoot, "fixture-console.txt");
const codexPath = process.env.CODEX_BIN || "codex";

mkdirSync(fixtureHome, { recursive: true, mode: 0o700 });
mkdirSync(fixtureWorkdir, { recursive: true, mode: 0o700 });

const versionResult = spawnSync(codexPath, ["--version"], {
  encoding: "utf8",
  env: { ...process.env, CODEX_HOME: fixtureHome },
});
assert.equal(versionResult.status, 0, versionResult.stderr);
const codexVersion = versionResult.stdout.trim();

const requests = [];
let requestSequence = 0;
let requestPhase = "setup";

function toolShape(body) {
  if (!Object.prototype.hasOwnProperty.call(body, "tools")) {
    return { state: "absent", count: null };
  }
  if (body.tools === null) return { state: "null", count: null };
  if (Array.isArray(body.tools)) return { state: "array", count: body.tools.length };
  return { state: typeof body.tools, count: null };
}

function safeToolChoice(value) {
  if (typeof value === "string") return value;
  if (value === null || value === undefined) return null;
  return { type: typeof value };
}

function writeJson(response, status, value) {
  const encoded = JSON.stringify(value);
  response.writeHead(status, {
    "content-type": "application/json",
    "content-length": Buffer.byteLength(encoded),
  });
  response.end(encoded);
}

function writeSuccessfulSse(response, model) {
  const responseId = `resp_fixture_${requestSequence}`;
  const messageId = `msg_fixture_${requestSequence}`;
  const outputText = "fixture-ready";
  const completedResponse = {
    id: responseId,
    object: "response",
    created_at: 0,
    status: "completed",
    error: null,
    incomplete_details: null,
    instructions: null,
    max_output_tokens: null,
    model,
    output: [{
      id: messageId,
      type: "message",
      status: "completed",
      role: "assistant",
      content: [{ type: "output_text", text: outputText, annotations: [] }],
    }],
    parallel_tool_calls: true,
    previous_response_id: null,
    reasoning: { effort: null, summary: null },
    store: false,
    temperature: null,
    text: { format: { type: "text" } },
    tool_choice: "auto",
    tools: [],
    top_p: null,
    truncation: "disabled",
    usage: {
      // Force the fresh ephemeral turn over the configured auto-compaction limit.
      input_tokens: 5000,
      input_tokens_details: { cached_tokens: 0 },
      output_tokens: 1,
      output_tokens_details: { reasoning_tokens: 0 },
      total_tokens: 5001,
    },
    metadata: {},
  };
  const events = [
    {
      type: "response.output_item.done",
      sequence_number: 0,
      output_index: 0,
      item: completedResponse.output[0],
    },
    {
      type: "response.completed",
      sequence_number: 1,
      response: completedResponse,
    },
  ];
  response.writeHead(200, {
    "content-type": "text/event-stream",
    "cache-control": "no-cache",
    connection: "close",
  });
  for (const event of events) {
    response.write(`event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`);
  }
  response.end();
}

const server = http.createServer((request, response) => {
  const chunks = [];
  let byteCount = 0;
  request.on("data", (chunk) => {
    byteCount += chunk.length;
    if (byteCount <= 16 * 1024 * 1024) chunks.push(chunk);
  });
  request.on("end", () => {
    requestSequence += 1;
    let body;
    try {
      body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
    } catch {
      writeJson(response, 400, { error: { message: "fixture received invalid JSON" } });
      return;
    }

    const tools = toolShape(body);
    const shape = {
      sequence: requestSequence,
      phase: requestPhase,
      method: request.method,
      path: request.url,
      model: typeof body.model === "string" ? body.model : null,
      input_count: Array.isArray(body.input) ? body.input.length : null,
      tools_state: tools.state,
      tools_count: tools.count,
      tool_choice: safeToolChoice(body.tool_choice),
      stream: body.stream === true,
    };
    requests.push(shape);

    const noTools = tools.state === "absent" || tools.state === "null" ||
      (tools.state === "array" && tools.count === 0);
    if (noTools && body.tool_choice !== undefined) {
      writeJson(response, 400, {
        error: {
          message: "A tool_choice was set on the request but no tools were specified",
          type: "invalid_request_error",
          param: "tool_choice",
          code: "invalid_argument",
        },
      });
      return;
    }

    writeSuccessfulSse(response, shape.model ?? "fixture-model");
  });
});

await new Promise((resolve, reject) => {
  server.once("error", reject);
  server.listen(0, "127.0.0.1", resolve);
});

const address = server.address();
assert(address && typeof address === "object");
const baseUrl = `http://127.0.0.1:${address.port}/v1`;
const providerConfig = `{name="Fixture loopback",base_url="${baseUrl}",wire_api="responses",requires_openai_auth=false}`;
const configArgs = [
  "-m", "fixture-model",
  "-c", "model_provider=\"fixture\"",
  "-c", `model_providers.fixture=${providerConfig}`,
  "-c", "model_context_window=1024",
  "-c", "model_auto_compact_token_limit=128",
];
const seedArgs = [
  "exec",
  "--ignore-user-config",
  "--ignore-rules",
  "--skip-git-repo-check",
  "--json",
  "--color", "never",
  "--sandbox", "read-only",
  "-C", fixtureWorkdir,
  ...configArgs,
  "-",
];
const reproduceArgs = [
  "exec", "resume", "--last",
  "--ephemeral",
  "--ignore-user-config",
  "--ignore-rules",
  "--skip-git-repo-check",
  "--json",
  ...configArgs,
  "-",
];

const childEnv = {
  ...process.env,
  CODEX_HOME: fixtureHome,
  HTTP_PROXY: "",
  HTTPS_PROXY: "",
  ALL_PROXY: "",
  http_proxy: "",
  https_proxy: "",
  all_proxy: "",
  NO_PROXY: "127.0.0.1,localhost",
  no_proxy: "127.0.0.1,localhost",
};

async function runCodex(args, prompt) {
  const child = spawn(codexPath, args, {
    cwd: fixtureWorkdir,
    env: childEnv,
    stdio: ["pipe", "pipe", "pipe"],
  });
  let stdout = "";
  let stderr = "";
  let stdinClosedEarly = false;
  child.stdout.setEncoding("utf8");
  child.stderr.setEncoding("utf8");
  child.stdout.on("data", (chunk) => { stdout += chunk; });
  child.stderr.on("data", (chunk) => { stderr += chunk; });
  child.stdin.on("error", (error) => {
    if (error.code === "EPIPE") {
      stdinClosedEarly = true;
      return;
    }
    throw error;
  });
  child.stdin.end(prompt);

  let timedOut = false;
  const timeout = setTimeout(() => {
    timedOut = true;
    child.kill("SIGTERM");
  }, 60_000);
  const exit = await new Promise((resolve) =>
    child.once("exit", (code, signal) => resolve({ code, signal }))
  );
  clearTimeout(timeout);
  return { ...exit, timedOut, stdinClosedEarly, stdout, stderr };
}

// The seed is stored only in the isolated temporary CODEX_HOME, then removed.
requestPhase = "seed";
const seed = await runCodex(seedArgs, "Synthetic fixture seed. Reply fixture-ready.");
requestPhase = "reproduction";
const reproduction = seed.code === 0
  ? await runCodex(reproduceArgs, "Synthetic fixture second turn.")
  : { code: null, signal: null, timedOut: false, stdinClosedEarly: false, stdout: "", stderr: "" };
await new Promise((resolve) => server.close(resolve));
rmSync(fixtureHome, {
  recursive: true,
  force: true,
  maxRetries: 5,
  retryDelay: 100,
});

const controlledError = "A tool_choice was set on the request but no tools were specified";
function sanitizedStdoutEvents(stdout) {
  return stdout.split(/\r?\n/).filter(Boolean).flatMap((line) => {
  try {
    const event = JSON.parse(line);
    const summary = { type: typeof event.type === "string" ? event.type : "unknown" };
    const message = typeof event.message === "string"
      ? event.message
      : typeof event.error?.message === "string"
        ? event.error.message
        : null;
    if (message?.includes(controlledError)) summary.message = controlledError;
    return [summary];
  } catch {
    return [];
  }
  });
}
function sanitizedStderrSignals(stderr) {
  return stderr.split(/\r?\n/)
  .filter((line) => line.includes(controlledError) || /pre-sampling compact/i.test(line))
  .map((line) => line.includes(controlledError) ? controlledError : "pre-sampling compact failure reported")
  .slice(0, 10);
}

const violatingRequests = requests.filter((request) =>
  request.tool_choice !== null &&
  (request.tools_state === "absent" || request.tools_state === "null" ||
    (request.tools_state === "array" && request.tools_count === 0))
);
const evidence = {
  generated_at: new Date().toISOString(),
  codex_version: codexVersion,
  invocations: {
    seed: {
      executable: codexPath,
      args: seedArgs.map((arg) => arg.replace(baseUrl, "http://127.0.0.1:<dynamic>/v1")),
      ephemeral: false,
      purpose: "Create synthetic history only inside the isolated temporary CODEX_HOME.",
    },
